INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q2', 3, 2, 'A flyer contains a headline, date, venue, price, and call to action (call to action (call to action (CTA))). Viewers remember the venue but miss the offer. Which explanation is strongest?', 'The venue should be removed because details are never useful', 'The colour set must be expanded to make the flyer lively', 'The order of importance gives secondary information too much visual weight', 'The call to action (call to action (call to action (CTA))) should be made smaller than all supporting text', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q3', 3, 3, 'Two colour pairs both match a brand style. Pair A is well-matched but the body text is hard to read; Pair B is slightly less well-matched but clearly legible. What is the best decision?', 'Choose Pair B or adjust Pair A until difference in light and dark and readability are adequate', 'Choose Pair A because harmony always outranks readability', 'Use both pairs on the same graphic without a system', 'Let the AI choose based on which sounds more professional', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q4', 3, 4, 'A client requests a square post, but the approved text is too long. What should the designer do first?', 'Reduce all text until it fits, regardless of reading size', 'Delete the call to action (call to action (call to action (CTA))) and publish the rest', 'Add more fancy elements to fill the layout', 'Edit for message priority, shorten text without changing facts, then test the layout', 'D', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q5', 3, 5, 'A learner uses one display font for the headline and another fancy font for body text. Why is this likely to fail?', 'Two fonts can never be used in one design', 'The roles compete and reduce readability; use distinct but compatible roles', 'The headline must always be in a serif font', 'The body text should be the largest element', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q6', 3, 6, 'A poster looks balanced when zoomed in but crowded on a phone. Which check is most useful?', 'Check the design only at 200% zoom', 'Add shadows to every text element', 'Preview at the size people will actually see and improve text size, spacing, and difference in light and dark', 'download at the largest possible file size', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q7', 3, 7, 'A brand guide describes the brand as calm, dependable, and welcoming, but uses chaotic spacing and aggressive type. What should be checked?', 'Whether the visual choices express the intended personality consistently', 'Whether the file has enough pages', 'Whether AI used advanced vocabulary', 'Whether the design includes every available Canva element', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q8', 3, 8, 'AI proposes the claim “delivery in 10 minutes” for Moremi Express, but no service data supports it. What should the learner do?', 'Keep it as an aspirational slogan', 'Add an asterisk without explanation', 'Use it only in a small font', 'Remove or verify the claim and use approved information only', 'D', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q9', 3, 9, 'A learner has two plausible layouts. What is the best way to choose between them?', 'Choose whichever took less time, without inspection', 'Compare both against the design instructions, audience, order of importance, readability, and call to action (call to action (call to action (CTA))) visibility', 'Choose the one with more effects', 'Ask AI which is objectively best and follow it', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q10', 3, 10, 'A heading appears uneven because the space between two specific letters is too tight. Which adjustment is most precise?', 'line spacing', 'letter spacing across the whole paragraph', 'space between two letters between the letter pair', 'Canvas dimensions', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q11', 3, 11, 'Body text is difficult to scan because lines sit too close together. Which change addresses the problem directly?', 'Adjust line spacing/line spacing and recheck paragraph length', 'Change only the filename', 'Increase letter spacing on the headline', 'Replace all shapes with icons', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q12', 3, 12, 'A flyer has a strong headline and attractive image but no clear next step. What should be added?', 'Another fancy slogan', 'A verified, clear and action-focused call to action (call to action (call to action (CTA))) placed within the order of importance', 'More brand colours', 'A second headline of equal size', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q13', 3, 13, 'A photo of food is cropped so the meal is visible but the text overlays the busiest part of the image. What is the best correction?', 'Increase the text effects until it dominates', 'Remove the headline', 'Use a more suitable crop or quiet text area and check difference in light and dark', 'Add more words over the image', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q14', 3, 14, 'The design meets the two-colour design instructions, but a red call to action (call to action (call to action (CTA))) disappears against a similar-toned background. What does this show?', 'A colour set rule alone does not guarantee sufficient difference in light and dark', 'Two-colour palettes are always unsuitable', 'CTAs should not use colour', 'The only fix is adding five more colours', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q15', 3, 15, 'Which evidence best shows that a learner made independent design decisions when using AI?', 'They used the longest AI prompt', 'They copied the first generated layout', 'They can explain specific changes against the design instructions and show the final Canva finished design', 'They submitted ten generated concepts without selecting one', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q16', 3, 16, 'A logo looks elegant in a wide header but becomes unreadable when placed in a small circular profile icon. What should be prepared?', 'A version made suitable for small-scale use, tested in the intended crop', 'A larger download only', 'A third font', 'A full paragraph inside the profile icon', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q17', 3, 17, 'A flyer has inconsistent margins and elements almost touch the edge. Which improvement is most best?', 'Add more border decorations', 'Use consistent safe margins and internal spacing, then check all edges', 'Move every element to the centre regardless of order of importance', 'Shrink the canvas until the edges disappear', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q18', 3, 18, 'A designer is asked to create a flyer for a campus health screening. Which content decision should be made before styling?', 'Which animation transition looks trendy', 'Which fancy font is most unusual', 'Which message, audience, verified details, and action the flyer must communicate', 'Which download setting creates the largest file', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q19', 3, 19, 'A heading is readable on a laptop but not on a projected or printed version. What should the designer do?', 'Test the actual output size and revise type size, weight, difference in light and dark, and spacing', 'Assume screen readability guarantees print readability', 'Add more text to explain the heading', 'Change only the file name', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q20', 3, 20, 'A peer says “make it pop” but gives no actionable detail. What is the best follow-up?', 'Add random effects until the peer approves', 'Ask which specific issue—order of importance, difference in light and dark, spacing, or focal point—needs improvement', 'Change the entire design without review', 'Ignore all peer feedback', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q21', 3, 21, 'A bakery flyer contains a price, but the source information is outdated. What should happen before download?', 'Make the price smaller', 'Ask AI to estimate a replacement', 'Publish and correct it if customers complain', 'Verify the current price or omit it', 'D', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q22', 3, 22, 'Which design is strongest for a social graphic intended to explain a process?', 'A single dense paragraph with fancy background', 'A clear sequence with concise steps, consistent alignment, and readable type', 'Five competing headlines', 'An image with no explanatory labels', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q23', 3, 23, 'A designer is choosing between a template and a blank canvas. What should determine the choice?', 'Whether the template fits the objective and can be adapted without compromising the design instructions', 'Whether the template requires no decisions', 'Whether the blank canvas is always more professional', 'Whether the template contains the most elements', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q24', 3, 24, 'A brand guide uses two fonts consistently, but both are difficult to read in small text. What is the best evaluation?', 'Consistency means the board is automatically successful', 'Only the headline matters', 'Retest font suitability at intended sizes and put first readable supporting type', 'Use the same two fonts but make every text line bold', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q25', 3, 25, 'An AI tool suggests a trendy design style unrelated to the audience. What should the learner do?', 'Adopt it because current trends always perform better', 'Use the trend only if it supports the design instructions and audience; otherwise reject it', 'Change the audience to match the suggestion', 'Submit the AI description instead of a design', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q26', 3, 26, 'Which review sequence is most effective before publishing a promotional flyer?', 'Effects, animations, filename, then content', 'colour set first and no other checks', 'download immediately, then ask whether the facts were right', 'Check design instructions and facts, order of importance, readability, spacing, call to action (call to action (call to action (CTA))), and final file size and shape', 'D', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q27', 3, 27, 'A poster’s smaller heading attracts attention before the headline. What is the most likely issue?', 'The order of importance is giving the wrong the intended order people read the content', 'The canvas is necessarily the wrong shape', 'The design needs more fonts', 'The call to action (call to action (call to action (CTA))) is too accurate', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q28', 3, 28, 'A student uses a photograph from an unknown online source. What should be checked?', 'Whether the photo has enough saturation only', 'Whether it matches the headline colour', 'permission to use the image, relevance, quality, and suitable crop', 'Whether AI can claim ownership', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q29', 3, 29, 'A client wants “premium” branding, but the target audience needs fast access to practical information. What should guide the design?', 'Use luxury effects even if details are hard to find', 'Balance the intended brand tone with audience needs and task clarity', 'Remove all practical information', 'Use the most expensive-looking template without review', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q30', 3, 30, 'A social graphic is attractive but users cannot identify what is being offered. What should be revised first?', 'Add texture to the background', 'Make the logo larger than the offer', 'Clarify the core message and make it prominent', 'Add several unrelated icons', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q31', 3, 31, 'Which statement best distinguishes margin from padding in a layout?', 'Margin is space outside an element; padding is space between its content and its boundary', 'They always mean exactly the same thing', 'Padding is the space between letters', 'Margin only applies to photos', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q32', 3, 32, 'A design uses a font that supports the the feeling the brand should give but lacks some characters needed for the text. What is the best response?', 'Remove the missing characters from the text', 'Use it regardless of rendering', 'Check whether the font includes the needed letters and symbols and select a compatible readable alternative if needed', 'Convert the whole flyer into a photograph', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q33', 3, 33, 'Which prompt is most likely to produce useful design concepts?', 'Make something cool', 'Create a professional design with no constraints', 'text a famous brand exactly', 'Suggest three simple flyer directions for campus food delivery, state audience and message, avoid invented claims, and explain layout rationale', 'D', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q34', 3, 34, 'A learner changes colours, fonts, image, and text simultaneously after poor feedback. Why is this a weak testing method?', 'It makes the design more consistent', 'It is difficult to identify which change improved or harmed the result', 'It prevents exporting', 'It guarantees no learning', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q35', 3, 35, 'A flyer’s call to action (call to action (call to action (CTA))) is visible but asks users to visit a link that has not been confirmed. What is the best practice?', 'Keep it because every flyer needs a link', 'Replace it with a made-up URL', 'Use a verified contact or ordering route, or hold publication until confirmed', 'Make the link smaller', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q36', 3, 36, 'A design is visually balanced but its headline, supporting details, and call to action (call to action (call to action (CTA))) all look equally important. What is missing?', 'A clear order of importance', 'A second colour set', 'A larger download file', 'More fancy icons', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q37', 3, 37, 'Which is the best basis for choosing an image for a campaign?', 'Choose the first image in search results', 'Select an image that fits the audience, message, quality, rights, and layout', 'Choose the most colourful image regardless of relevance', 'Use an image even if it contradicts the offer', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q38', 3, 38, 'The same campaign must be adapted to a poster and a square social post. What should remain consistent?', 'Every element’s exact position and size', 'The identical crop even if content is cut off', 'The core message and brand style, while layout adapts to each format', 'All text must remain the same size', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q39', 3, 39, 'Which is the best evidence for assessment for a final branded graphic?', 'A polished image only, with no explanation', 'A list of definitions', 'A screenshot of AI output only', 'The final finished design plus a rationale linking choices to audience, objective, order of importance, and verified content', 'D', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q40', 3, 40, 'A learner has 30 minutes to improve a weak flyer. What should be put first?', 'Fix the highest-impact communication failures first: message, order of importance, readability, and call to action (call to action (call to action (CTA)))', 'Perfect tiny fancy details first', 'Add more effects before checking text', 'Rebuild everything from scratch without explanation', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q41', 3, 41, 'A social graphic is being resized from square to a tall story format. Which approach best preserves communication quality?', 'Stretch the square artwork vertically until it fills the canvas', 'Keep all objects at identical coordinates even if text overlaps', 'Recompose the layout for the new aspect ratio while preserving the message and order of importance', 'Remove the headline to make the resize easier', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q42', 3, 42, 'A food photograph is visually strong but its colours clash with the established brand colour set. What is the best design judgement?', 'Use it unchanged because photography must never be adjusted', 'Assess whether a suitable crop or restrained treatment can harmonise it without showing inaccurately the food', 'Replace the brand colour set with the photograph''s colours automatically', 'Cover most of the photo with fancy shapes', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q43', 3, 43, 'A flyer includes a QR code, but it has not been tested after download. What should happen before distribution?', 'Test the exported QR code on a phone and confirm that it leads to the intended destination', 'Increase its fancy border only', 'Assume it works because it appears sharp', 'Add a second untested QR code', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q44', 3, 44, 'A headline is concise, but the supporting text repeats the same idea three times. What is the strongest revision?', 'Make the headline longer', 'Increase the font size of every paragraph', 'Add another slogan to fill space', 'Remove redundant text while retaining necessary details and the next step', 'D', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q45', 3, 45, 'A designer uses a low-resolution logo that looks blurred in print. Which corrective action is best?', 'Sharpen it repeatedly until it appears scalable-based', 'Obtain a suitable high-quality or scalable logo asset and inspect the final download', 'Enlarge the blurred image further', 'Place a shadow behind it', 'B', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q46', 3, 46, 'A layout has consistent alignment but feels monotonous. What is the best next change?', 'Randomly rotate elements', 'Break all alignment rules', 'Introduce controlled variation in scale or emphasis while retaining a clear grid', 'Add a different font to every text block', 'C', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
