INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q51', 3, 51, 'An image subject is partly hidden behind a headline. Which response is most appropriate?', 'Adjust the crop or reposition the text to preserve the subject and readability', 'Add more text over the subject', 'Shrink the whole canvas', 'Increase saturation until the subject is clearer', 'A', '2026-10-17 05:54:50') ON CONFLICT (id) DO NOTHING;
