INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q99', 3, 99, 'A learner has used a template''s stock photo, but it depicts a different product from the actual offer. What is the best action?', 'Replace it with a relevant, accurate visual or clearly non-literal illustration', 'Keep it because stock images are generic', 'Add more filters to make it abstract', 'Hide the product label', 'A', '2026-10-17 05:54:51') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e3_q100', 3, 100, 'A designer is comparing a highly legible layout with a more fashionable but harder-to-read one. Which principle should lead the decision?', 'Fashion always takes priority', 'Readability matters only for long documents', 'The fashionable layout must be chosen for originality', 'The design style should serve the objective and audience; style should not undermine comprehension', 'D', '2026-10-17 05:54:51') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q1', 5, 1, 'Moremi Express reaches 12,000 accounts, receives 400 likes, 45 link clicks, and 3 completed orders. The objective was orders. What is the most defensible conclusion?', 'The campaign succeeded because reach was high', 'The audience definitely rejected the service', 'Reach and engagement occurred, but order completion of the intended action appears weak and the path should be investigated', 'The campaign should be judged only by likes', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q2', 5, 2, 'A campaign objective is to generate qualified enquiries. Which success measure (KPI) is closest to the objective?', 'Total follower count', 'Number of relevant enquiries and cost per qualified enquiry, if paid', 'Number of posts published', 'The creator’s personal rating', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q3', 5, 3, 'An AI audience profile says “all students prefer late-night delivery,” based on no data. How should it be used?', 'As a hypothesis to validate, not a verified audience insight', 'As the campaign’s factual foundation', 'As a testimonial', 'As a reason to claim 24-hour availability', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q4', 5, 4, 'A post earns many saves and questions but few likes. Its purpose is to explain how ordering works. What should the marketer assess?', 'Whether the colour palette is trendy', 'Whether the post should be deleted for low likes', 'Whether every person who saved it ordered', 'Whether questions and feedback indicate improved understanding, and what remains unclear', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q5', 5, 5, 'Platform A has a larger audience; Platform B produces more relevant enquiries and the team can manage it well. What is the strongest decision?', 'Move all resources to A because reach is always superior', 'Prioritise B while continuing to compare relevant outcomes and capacity', 'Split resources equally forever', 'Abandon measurement', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q6', 5, 6, 'A content calendar includes date, topic, and format but no audience or objective. What is the main planning weakness?', 'It is too colourful', 'It contains too many dates', 'It lacks a reasoned connection between content and intended audience outcome', 'It must include paid ads', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q7', 5, 7, 'A caption promises “free delivery to every hostel,” but coverage and pricing are unconfirmed. What should the marketer do?', 'Publish because specific offers improve persuasion', 'Ask AI to confirm the offer', 'Change “free” to “fast” and publish', 'Verify the offer and coverage or remove the unsupported claim', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q8', 5, 8, 'A campaign aims to generate direct messages, but the call to action (CTA) says “Follow for more.” What is the issue?', 'The call to action (CTA) requests an action that does not match the stated objective', 'The caption is too short by definition', 'The audience must be changed', 'Every call to action (CTA) should be a question', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q9', 5, 9, 'A report shows reach increased 40%, but enquiries were not tracked. Which report statement is honest?', 'Sales rose by 40%', 'The campaign was profitable', 'Reach increased, but enquiry and completion of the intended action impact cannot be determined from the available data', 'The campaign failed completely', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q10', 5, 10, 'A team wants to test two call to action (CTA) wordings. Which method produces more interpretable evidence?', 'Change call to action (CTA), image, audience, and budget at the same time', 'Define the target action, keep other conditions reasonably similar, and compare relevant action rates', 'Ask AI to select a winner', 'Compare follower counts months later', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q11', 5, 11, 'Customer messages repeatedly ask whether the service covers a particular campus. What is the best content opportunity?', 'Create a verified coverage FAQ and update it when service information changes', 'Invent a coverage map to look complete', 'Ignore private questions', 'Post unrelated trending content', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q12', 5, 12, 'A audience profile includes age, campus, goals, pain points, and assumptions, but no source notes. What improvement matters most?', 'Add a fictional biography', 'Give the audience profile a more memorable name', 'Make the profile longer', 'Label known facts, assumptions, and research gaps, noting where evidence came from', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q13', 5, 13, 'Educational content earns saves and repeat questions; promotional posts get few enquiries. What should happen next?', 'Stop educational content because it does not sell immediately', 'Review which questions remain unanswered and diagnose offer clarity, call to action (CTA), and ordering path on promotional posts', 'Repeat the same promotion without change', 'Claim education guarantees completion o the intended action', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q14', 5, 14, 'The business has limited staff and cannot respond quickly on four platforms. What is the best operating choice?', 'Open four accounts anyway to appear established', 'Post on every platform but disable messages', 'Prioritise channels that fit the audience and goals, with capacity for timely responses', 'Choose the platforms with the most features', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q15', 5, 15, 'An AI-generated calendar contains useful themes but repeats the same objective every day. How should it be improved?', 'Map posts to distinct needs and objectives such as awareness, education, trust, engagement, and completion of the intended action', 'Use the same caption with different emojis', 'Replace every post with a discount', 'Remove the audience definition', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q16', 5, 16, 'A testimonial includes a customer’s full name, phone number, and private order details. What should be done before publication?', 'Publish because positive feedback is valuable', 'Let AI anonymise it without review', 'Obtain appropriate permission and remove private details that are not necessary to share', 'Keep details but shrink the text', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q17', 5, 17, 'A post gets 500 clicks, but users report that the ordering page is confusing. What should the marketer investigate?', 'Change the logo and target audience simultaneously', 'The post’s colour only', 'Whether clicks are a number that looks impressive but may not show success and should never be tracked', 'The landing/order experience and friction after the click, while retaining click data', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q18', 5, 18, 'Which prompt best constrains AI when drafting a weekly content calendar?', 'Create viral content at any cost', 'Use only supplied facts; flag missing information; return a table with date, audience, objective, format, call to action (CTA), and measurement', 'Invent realistic prices if none are supplied', 'Write captions without context', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q19', 5, 19, 'A local campaign has high engagement, mostly from people outside the service area. What is the most useful next analysis?', 'Audience relevance, distribution settings, content cues, and the geographic fit of the platform', 'Whether to stop tracking all engagement', 'Whether to add unrelated hashtags', 'Whether the business should claim nationwide coverage', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q20', 5, 20, 'A post intended to build awareness receives many impressions but little recall or recognition data. What can be concluded?', 'Awareness definitely improved', 'The campaign failed', 'Impressions occurred, but the available metric alone does not establish meaningful awareness or recall', 'Every impression was from a target customer', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q21', 5, 21, 'A marketer has only a few customer conversations. Which audience profile statement is most responsible?', 'All students value cheap meals above everything', 'No student will use an ordering page', 'Every customer is price-sensitive', 'Some students interviewed mentioned price; broader preferences need further research', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q22', 5, 22, 'The owner wants every post to sell immediately. What is the likely strategic weakness?', 'Every social post must have a sales call to action (CTA)', 'Content roles may be mismatched to audience readiness and the intended objective', 'Educational content is always useless', 'Sales outcomes can be measured through likes alone', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
