INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q40', 5, 40, 'Before using a customer audience profile to target paid content, what should be done?', 'Treat all AI details as customer research', 'Use every demographic statement as a rule', 'Validate important claims, separate assumptions from evidence, and avoid unsupported sensitive inferences', 'Invent a sample size to make it credible', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
