INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q43', 5, 43, 'A team has a limited budget and two campaign objectives: broad awareness and qualified enquiries. What should the plan do?', 'Use one success measure (KPI) for both objectives regardless of purpose', 'Optimise only for the cheapest impressions', 'Avoid defining success until the campaign ends', 'Define separate objectives and measures, allocating effort according to priority and capacity', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
