INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q47', 5, 47, 'The team wants to claim that a new content series improved customer trust. Which evidence would be most appropriate?', 'A larger reach number alone', 'The number of posts produced', 'The AI tool''s confidence score', 'Relevant feedback, recurring trust-related questions, or other appropriate indicators, with limitations acknowledged', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q48', 5, 48, 'A content plan uses a audience profile built from a few interviews. What is the best way to present it?', 'As a definitive profile of all customers', 'As a working hypothesis, documenting evidence, assumptions, and research gaps', 'As a verified market census', 'As a source of guaranteed sales predictions', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q49', 5, 49, 'A business has 10,000 followers but receives few relevant enquiries. What is the strongest first diagnostic?', 'Buy more followers', 'Post at every hour', 'Check audience fit, offer clarity, call to action (CTA), enquiry route, and relevant performance data', 'Change the logo immediately', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q50', 5, 50, 'An educational post is saved frequently but receives few comments. Its objective is to help users understand ordering. What should the marketer do?', 'Assess saves, feedback, and whether customer confusion is reduced rather than judging by comments alone', 'Delete it because comments are the only useful measure', 'Assume every save became an order', 'Change the objective after seeing the result', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q51', 5, 51, 'A team tests a new content format but simultaneously changes the audience, offer, budget, and call to action (CTA). What is the main issue?', 'It makes the campaign more scientific', 'It guarantees a larger sample', 'It removes all external influences', 'The result will be difficult to attribute to any one change', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q52', 5, 52, 'A customer asks a repeated question about payment methods, but the business has not approved a list. What should the content team do?', 'Invent common payment methods to answer quickly', 'Confirm the approved methods and then publish an accurate FAQ', 'Ask AI to infer the methods', 'Avoid the question permanently', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q53', 5, 53, 'A campaign has a high cost per enquiry but the enquiries are highly qualified and often convert. What should the team consider?', 'Stop the campaign based only on cost per enquiry', 'Compare only impressions', 'Evaluate cost alongside lead quality, downstream completion of the intended action, and business value', 'Assume high cost always means failure', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q54', 5, 54, 'The owner wants to publish a customer screenshot that includes a phone number and private message. What is the proper step?', 'Obtain appropriate permission and remove private information not needed for the story', 'Publish it because it is genuine', 'Use AI to guess whether consent exists', 'Blur only the business logo', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q55', 5, 55, 'An AI tool proposes five posts with different prices for the same service. The business has provided no price list. What should happen?', 'Pick the lowest price to attract attention', 'Use different prices on each platform', 'Publish the most plausible price', 'Remove the invented prices and request verified information if pricing is required', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q56', 5, 56, 'A post''s reach is low, but the few people reached are within the intended service area and several enquire. What is the most useful analysis?', 'Reach is low, so the post has no value', 'Assess the quality and rate of relevant actions while considering whether broader reach is also needed', 'Assume every viewer will order', 'Replace the audience with a broader one immediately', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q57', 5, 57, 'A content calendar contains only promotional posts and no answers to common customer questions. What risk does this create?', 'The business will automatically gain more sales', 'Educational content always reduces sale', 'Potential customers may lack information needed to evaluate or use the service', 'The platform will block all promotional posts', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q58', 5, 58, 'The team wants to compare Instagram and TikTok for a local campaign. Which comparison is most useful?', 'Relevant audience reached, actions aligned to the objective, content fit, and management effort', 'Total global user counts only', 'Which platform the owner likes', 'The number of filters each platform offers', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q59', 5, 59, 'A report states that reach increased by 25% and concludes that revenue rose. What is wrong with the conclusion?', 'Reach and revenue are identical', 'Revenue always rises with reach', 'The report should use more emojis', 'Reach alone does not establish revenue change; revenue or completion of the intended action evidence is needed', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q60', 5, 60, 'A campaign has a high number of DMs, but many are spam or outside the service area. Which success measure (KPI) refinement is best?', 'Count every DM as equally valuable', 'Measure qualified enquiries using clear criteria and track the proportion that meet them', 'Stop recording messages', 'Use follower growth as the only measure', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q61', 5, 61, 'A audience profile says students prefer low prices, but actual enquiry data shows repeated questions about reliability and collection points. What should guide the next content plan?', 'Ignore the data because audience profiles are permanent', 'Publish only discounts', 'Use the data to revisit the price assumption and address reliability or pickup questions with verified information', 'Claim that every student prioritises reliability', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q62', 5, 62, 'The team needs a prompt to generate distinct campaign ideas without inventing facts. Which instruction is strongest?', 'Request ideas mapped to separate objectives, audience needs, formats, approved facts, constraints, and clearly labelled assumptions', 'Ask for viral posts only', 'Tell AI to fill all missing facts confidently', 'Request the longest possible calendar', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q63', 5, 63, 'A post was designed to generate ordering-page visits. It receives many likes but very few clicks. What is the most useful next step?', 'Declare the post successful because engagement is high', 'Change the business name', 'Increase posting frequency without reviewing the post', 'Review message-to-link consistency, call to action (CTA) clarity, audience fit, and click data', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q64', 5, 64, 'A business publishes a weekly menu, but items change frequently. How can the team reduce outdated claims?', 'Publish a permanent menu from AI suggestions', 'Date the information and establish a verification/update process before each publication', 'Avoid all menu content', 'Use old menu images because they look better', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q65', 5, 65, 'A new campaign is being planned with no baseline data. How should success be evaluated?', 'Promise a fixed completion of the intended action rate in advance', 'Compare results to an invented industry average', 'Set a clear initial objective and track a baseline, documenting limitations and learning for future comparisons', 'Skip measurement until the business grows', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q66', 5, 66, 'A marketer wants to improve response time to enquiries. Which operational metric is most relevant?', 'Response-time distribution and the share of enquiries answered within the agreed service window', 'Number of hashtags', 'Reach alone', 'Number of Canva templates', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q67', 5, 67, 'A content calendar has strong objectives but assigns more posts than the team can produce and moderate. What should be revised?', 'The target audience only', 'All KPIs should be replaced with likes', 'The business must open more platforms immediately', 'Reduce or sequence the workload to match production and response capacity', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q68', 5, 68, 'A customer complaint is posted publicly. Which response best supports a professional presence?', 'Delete all criticism without review', 'Acknowledge respectfully, avoid exposing private details, and move sensitive resolution to an appropriate channel while following up', 'Argue with the customer publicly', 'Make a promise that the issue will never happen again without investigation', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q69', 5, 69, 'An influencer offers to promote the service but their audience is mostly outside the service area. What should be checked before agreeing?', 'Follower count only', 'Whether the influencer has a visually attractive profile', 'Audience-location fit, engagement quality, credibility, deliverables, cost, and measurable objective', 'Whether AI describes the influencer as popular', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q70', 5, 70, 'A campaign receives 200 clicks but the website analytics may be misconfigured. What should happen before drawing conclusions about completed actions?', 'Check tracking setup and reconcile available data, clearly noting any gaps', 'Assume the campaign made 200 sales', 'Stop collecting analytics permanently', 'Report the highest possible completion of the intended action estimate', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q71', 5, 71, 'A content creator uses a trending audio clip in a commercial post. What must be checked?', 'Whether the audio is popular only', 'Whether the caption contains enough emojis', 'Whether the audio matches the logo colour', 'Whether the audio is permitted for the intended commercial use and platform context', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q72', 5, 72, 'The team wants to publish a statistic about student food spending but has no source. Which option is responsible?', 'Use a plausible number and round it', 'Find a credible source or omit the statistic; label any hypothesis clearly', 'Cite the AI tool as the data source', 'Publish it as an industry fact', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q73', 5, 73, 'A business has many profile visits but few message enquiries. Which analysis is most relevant?', 'Increase the number of hashtags only', 'Assume the profile visitors are not real people', 'Review profile clarity, trust signals, offer relevance, call to action (CTA) visibility, and the message path', 'Change every platform at once', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q74', 5, 74, 'A team has tested two captions on different days with different offers and different audiences. Can it attribute the result to caption wording alone?', 'No; too many conditions differ to isolate the effect of wording', 'Yes, because the captions were different', 'Yes, if one caption received more likes', 'Only AI can determine the cause', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q75', 5, 75, 'A content report includes reach, likes, and comments but the objective was to generate bookings. What is missing?', 'A longer report introduction', 'More screenshots of the posts', 'A count of all available emojis', 'Booking-related measures and a clear explanation of whether tracking supports conclusions about the objective', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q76', 5, 76, 'An AI audience profile contains sensitive assumptions about individual students. What is the safest planning approach?', 'Use the assumptions for targeting because they are detailed', 'Remove unsupported sensitive inferences and base decisions on relevant, appropriate evidence', 'Publish the audience profile publicly to ask for reactions', 'Treat AI-generated demographic details as verified', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q77', 5, 77, 'A business wants to use a customer''s review in an ad. What should be verified?', 'Whether the review can be rewritten to sound stronger', 'Whether AI can create a matching photograph', 'Authenticity, permission for the intended use, accurate quotation, and any necessary disclosure', 'Whether the review guarantees sales', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q78', 5, 78, 'A post performs well in engagement but generates questions showing users misunderstood the offer. What should be improved?', 'Clarify the offer and supporting information, then test whether understanding improves', 'Repeat the same post because engagement was high', 'Remove all explanatory text', 'Claim the audience misunderstood because it is not the target', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q79', 5, 79, 'A campaign objective is brand awareness in a defined local area. Which reporting combination is most informative?', 'Total follower count over the life of the account only', 'Number of posts produced', 'The owner''s opinion and AI''s score', 'Relevant local reach or impressions, audience fit, and suitable awareness indicators with caveats', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q80', 5, 80, 'A team is deciding whether to boost a post that received many likes. What should it check first?', 'Whether the post has the brightest colours', 'Whether the post aligns with a defined objective, target audience, completion of the intended action path, and measurable success criteria', 'Whether the caption is the longest', 'Whether competitors have liked it', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q81', 5, 81, 'An AI-generated content calendar uses a different tone and different service facts on each platform. What should remain consistent?', 'Every word and format must be identical', 'The platform should determine service prices', 'Approved facts, core brand identity, and campaign objective, while execution adapts to each channel', 'The call to action (CTA) should be omitted everywhere', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q82', 5, 82, 'A team reports a 50% increase in messages after changing both the call to action (CTA) and the posting frequency. What is the correct interpretation?', 'Messages increased after the combined changes, but the separate contribution of each change is unknown', 'The call to action (CTA) alone caused the increase', 'Posting frequency alone caused the increase', 'The campaign''s revenue also increased by 50%', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q83', 5, 83, 'A local business wants to build trust but has no testimonials approved for use. Which content approach is appropriate?', 'Invent anonymised testimonials', 'Ask AI to write a realistic customer story and publish it', 'Claim hundreds of satisfied customers without evidence', 'Use verified process explanations, accurate FAQs, and transparent service information', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q84', 5, 84, 'A calendar assigns a success measure (KPI) of “engagement” to every post. Why is this inadequate?', 'Engagement is never useful', 'The measure is too broad unless defined and may not match each post''s objective', 'Every post must use revenue as its success measure (KPI)', 'It guarantees no comparisons can be made', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q85', 5, 85, 'A campaign generates qualified leads, but the business cannot follow up for several days. What should be considered before scaling spend?', 'Increase spend to create urgency', 'Stop all content creation', 'Improve lead handling capacity and follow-up processes before generating more demand than the team can serve', 'Change the logo', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q86', 5, 86, 'A marketer wants to claim that a new posting time caused better results based on one post. What should be done?', 'Treat the result as preliminary and repeat a controlled test across comparable posts before making a strong claim', 'Declare the time universally optimal', 'Ask AI to confirm causality', 'Delete the earlier results', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q87', 5, 87, 'A customer asks whether the service is available on a public holiday. The schedule is unconfirmed. What is the best response?', 'Say yes to avoid losing the enquiry', 'Use last month''s schedule without checking', 'Ask AI to predict the opening hours', 'Verify the current schedule or state that confirmation is needed before making a promise', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q88', 5, 88, 'A campaign has fewer clicks but a higher proportion of completed orders from those clicks. What should the marketer compare?', 'Clicks alone', 'Both volume and quality of outcomes, including completion of the intended action rate and total business objective', 'Likes alone', 'The number of content formats', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q89', 5, 89, 'A business is adapting a campaign for WhatsApp Status and Instagram. Which adaptation is most appropriate?', 'Post the same dimensions and copy regardless of placement', 'Use a different offer on each platform without approval', 'Preserve the core message and approved facts while adapting layout, pacing, and call to action (CTA) to each channel''s use', 'Remove all calls to action', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q90', 5, 90, 'A content plan includes a customer poll. What should happen with the responses?', 'Review them as feedback from participating users, note sampling limits, and use them to guide further questions or tests', 'Treat the poll as a representative survey of every customer', 'Publish all names and answers automatically', 'Ignore the results if they disagree with the audience profile', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q91', 5, 91, 'A business has high reach but little awareness among the intended local audience. Which adjustment is most relevant?', 'Increase global reach regardless of audience', 'Add more general hashtags without analysis', 'Make the caption longer by default', 'Review targeting/distribution, local relevance, and audience signals, then measure relevant reach', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q92', 5, 92, 'A creator proposes an urgent “last chance” message, but there is no real deadline. What should the marketer do?', 'Use it because urgency improves all campaigns', 'Remove the false urgency and use a truthful reason to act, if one exists', 'Add a countdown graphic without a deadline', 'Ask AI to invent a deadline', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q93', 5, 93, 'A weekly report shows a rise in followers and a drop in qualified enquiries. What is the strongest next step?', 'Conclude the account is growing successfully', 'Stop tracking follower growth entirely', 'Investigate audience relevance, content mix, and enquiry path rather than treating follower growth as the sole success measure', 'Buy ads for more followers immediately', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q94', 5, 94, 'A content calendar is approved, but the menu and coverage details change before scheduled posts go live. What should the team do?', 'Re-verify time-sensitive facts immediately before publication and update or pause affected posts', 'Publish because approval makes details permanent', 'Let AI estimate current details', 'Keep old details in small text', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q95', 5, 95, 'A marketer wants to compare performance across platforms with very different audience sizes. Which reporting practice helps?', 'Compare raw likes only', 'Ignore differences in objectives', 'Use the platform with the largest numbers as the winner', 'Compare goal-relevant rates and outcomes alongside absolute volumes, explaining context and limitations', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q96', 5, 96, 'A customer asks for a refund policy in comments, but the approved policy is not available. What should the account manager do?', 'Invent a standard policy', 'Acknowledge the question and obtain the approved policy before answering definitively', 'Delete the comment automatically', 'Promise a full refund to maintain goodwill', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q97', 5, 97, 'An AI tool generates a list of popular hashtags and claims they will guarantee viral reach. What should the marketer do?', 'Use all hashtags because AI is confident', 'Treat virality as guaranteed if enough hashtags are added', 'Treat them as suggestions, check relevance and platform fit, and make no guarantee about reach', 'Replace audience research with hashtags', 'A', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q98', 5, 98, 'A team wants to know whether an FAQ reduced repeated enquiries. Which approach is strongest?', 'Compare the pattern of relevant repeated questions before and after, account for other changes where possible, and state limits', 'Assume the FAQ worked because it was published', 'Count likes on the FAQ only', 'Ask AI whether the questions reduced', 'D', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q99', 5, 99, 'A campaign attracts a large number of enquiries but many people misunderstood the price. What is the most useful corrective action?', 'Increase the number of enquiries before revising content', 'Remove all price information permanently', 'Make the caption more dramatic', 'Clarify verified pricing and conditions in the content and check whether misunderstanding decreases', 'B', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, q_num, question, opt_a, opt_b, opt_c, opt_d, answer, updated_at) VALUES ('e5_q100', 5, 100, 'A content creator wants to repurpose a customer photo from a private group. What should be checked?', 'Whether it will fit the layout only', 'Permission and privacy expectations for public/commercial reuse, plus relevance and accuracy', 'Whether AI can remove the background', 'Whether the post is likely to get likes', 'C', '2026-10-17 05:55:34') ON CONFLICT (id) DO NOTHING;
